@property
def install_info(self):
    """
    Returns role install info
    """
    if self._install_info is None:

        info_path = os.path.join(self.path, self.META_INSTALL)
        if os.path.isfile(info_path):
            try:
                f = open(info_path, 'r')
                self._install_info = yaml.safe_load(f)
            except Exception:
                display.vvvvv("Unable to load Galaxy install info for %s" % self.name)
                return False
            finally:
                f.close()
    return self._install_info


    no_deps = context.CLIARGS['no_deps']
    force_deps = context.CLIARGS['force_with_deps']

    force = context.CLIARGS['force'] or force_deps

    roles_left = []
    if parsed_roles is not None:
        roles_left = parsed_roles
    else:
        # roles were specified directly, so we'll just go out grab them
        # (and their dependencies, unless the user doesn't want us to).
        for rname in context.CLIARGS['args']:
            role = RoleRequirement.role_yaml_parse(rname.strip())
            roles_left.append(GalaxyRole(self.galaxy, self.api, **role))

    for role in roles_left:
        # only process roles in roles files when names matches if given
        if role_file and context.CLIARGS['args'] and role.name not in context.CLIARGS['args']:
            display.vvv('Skipping role %s' % role.name)
            continue

        display.vvv('Processing role %s ' % role.name)

        # query the galaxy API for the role data

        if role.install_info is not None:
            if role.install_info['version'] != role.version or force:
                if force:
                    display.display('- changing role %s from %s to %s' %
                                    (role.name, role.install_info['version'], role.version or "unspecified"))
                    role.remove()
                else:
                    display.warning('- %s (%s) is already installed - use --force to change version to %s' %
                                    (role.name, role.install_info['version'], role.version or "unspecified"))
                    continue
            else:
                if not force:
                    display.display('- %s is already installed, skipping.' % str(role))
                    continue

        try:
            installed = role.install()
        except AnsibleError as e:
            display.warning(u"- %s was NOT installed successfully: %s " % (role.name, to_text(e)))
            self.exit_without_ignore()
            continue

        # install dependencies, if we want them
        if not no_deps and installed:
            if not role.metadata:
                display.warning("Meta file %s is empty. Skipping dependencies." % role.path)
            else:
                role_dependencies = (role.metadata.get('dependencies') or []) + role.requirements
                for dep in role_dependencies:
                    display.debug('Installing dep %s' % dep)
                    dep_req = RoleRequirement()
                    dep_info = dep_req.role_yaml_parse(dep)
                    dep_role = GalaxyRole(self.galaxy, self.api, **dep_info)
                    if '.' not in dep_role.name and '.' not in dep_role.src and dep_role.scm is None:
                        # we know we can skip this, as it's not going to
                        # be found on galaxy.ansible.com
                        continue
                    if dep_role.install_info is None:
                        if dep_role not in roles_left:
                            display.display('- adding dependency: %s' % to_text(dep_role))
                            roles_left.append(dep_role)
                        else:
                            display.display('- dependency %s already pending installation.' % dep_role.name)
                    else:
                        if dep_role.install_info['version'] != dep_role.version:
                            if force_deps:
                                display.display('- changing dependant role %s from %s to %s' %
                                                (dep_role.name, dep_role.install_info['version'], dep_role.version or "unspecified"))
                                dep_role.remove()
                                roles_left.append(dep_role)
                            else:
                                display.warning('- dependency %s (%s) from role %s differs from already installed version (%s), skipping' %
                                                (to_text(dep_role), dep_role.version, role.name, dep_role.install_info['version']))
                        else:
                            if force_deps:
                                roles_left.append(dep_role)
                            else:
                                display.display('- dependency %s is already installed, skipping.' % dep_role.name)

        if not installed:
            display.warning("- %s was NOT installed successfully." % role.name)
            self.exit_without_ignore()

    return 0
